-- C37 local qualification ACL. Execute as isolated fixture owner on fresh restricted logins.
-- Credentials are provisioned separately. The disposition custodian has its existing independent custody.
BEGIN;
SET LOCAL search_path TO pg_catalog,public,pg_temp;
GRANT SELECT ON public.alembic_version, public.classroom_classes, public.classroom_class_states, public.classroom_programs, public.classroom_role_grants, public.classroom_teaching_assignments, public.classroom_school_authorizations, public.classroom_membership_holds, public.classroom_entitlements, public.classroom_student_memberships, public.classroom_membership_periods, public.trusted_verifiers, public.woodchuck_profiles, public.account_privacy_rules, public.child_consent_evidence, public.classroom_entry_codes, public.organizations, public.classroom_ownership_transfers, public.classroom_roster_identities, public.child_pending_consents, public.child_kws_verifications, public.classroom_guardian_authorizations, public.classroom_guardian_recipients TO c37_hold_writer;
GRANT SELECT(id,version,identity_id,program_id,profile_id) ON public.classroom_roster_identity_audits TO c37_hold_writer;
GRANT EXECUTE ON FUNCTION public.c37_lock_hold_consent(integer,integer,integer,integer,integer) TO c37_hold_writer;
GRANT UPDATE(display_name) ON public.trusted_verifiers TO c37_hold_writer;
GRANT UPDATE(display_name) ON public.classroom_classes TO c37_hold_writer;
GRANT UPDATE(created_at) ON public.classroom_programs TO c37_hold_writer;
GRANT UPDATE(updated_at) ON public.classroom_class_states TO c37_hold_writer;
GRANT UPDATE(created_at) ON public.classroom_student_memberships TO c37_hold_writer;
GRANT UPDATE(display_name) ON public.woodchuck_profiles TO c37_hold_writer;
GRANT INSERT(membership_id, state, reason, held_by_verifier_id, held_at, released_at, released_by_verifier_id), UPDATE(state, reason, held_by_verifier_id, held_at, released_at, released_by_verifier_id) ON public.classroom_membership_holds TO c37_hold_writer;
GRANT INSERT(membership_id, state, starts_at, ended_at, ended_reason), UPDATE(ended_at, ended_reason) ON public.classroom_membership_periods TO c37_hold_writer;
GRANT INSERT(program_id, class_id, profile_id, membership_id, actor_verifier_id, actor_profile_id, actor_admin, action, reason, entitlement_id, code_id, occurred_at) ON public.classroom_s2_audit_events TO c37_hold_writer;
GRANT SELECT(id) ON public.classroom_s2_audit_events TO c37_hold_writer;
GRANT SELECT(id) ON public.classroom_membership_periods TO c37_hold_writer;
GRANT USAGE ON SEQUENCE public.classroom_s2_audit_events_id_seq, public.classroom_membership_periods_id_seq TO c37_hold_writer;
GRANT SELECT ON public.alembic_version, public.classroom_classes, public.classroom_class_states, public.classroom_programs, public.classroom_role_grants, public.classroom_teaching_assignments, public.classroom_school_authorizations, public.classroom_membership_holds, public.classroom_entitlements, public.classroom_student_memberships, public.classroom_membership_periods, public.trusted_verifiers, public.woodchuck_profiles, public.account_privacy_rules, public.child_consent_evidence, public.classroom_entry_codes, public.organizations, public.classroom_ownership_transfers, public.classroom_roster_identities, public.child_pending_consents, public.child_kws_verifications, public.classroom_guardian_authorizations, public.classroom_guardian_recipients TO c37_program_authority;
GRANT SELECT(id,version,identity_id,program_id,profile_id) ON public.classroom_roster_identity_audits TO c37_program_authority;
GRANT EXECUTE ON FUNCTION public.c37_lock_hold_consent(integer,integer,integer,integer,integer) TO c37_program_authority;
GRANT INSERT(organization_id, owner_verifier_id, owner_version, created_at), UPDATE(owner_verifier_id, owner_version) ON public.classroom_programs TO c37_program_authority;
GRANT INSERT(program_id, verifier_id, role, starts_at, granted_by_verifier_id, ended_at, ended_reason, ended_by_verifier_id), UPDATE(ended_at, ended_reason, ended_by_verifier_id) ON public.classroom_role_grants TO c37_program_authority;
GRANT INSERT(program_id, class_id, verifier_id, starts_at, granted_by_verifier_id, ended_at, ended_reason, ended_by_verifier_id), UPDATE(ended_at, ended_reason, ended_by_verifier_id) ON public.classroom_teaching_assignments TO c37_program_authority;
GRANT INSERT(program_id, initiator_verifier_id, recipient_verifier_id, owner_version, status, created_at, resolved_at), UPDATE(status, resolved_at) ON public.classroom_ownership_transfers TO c37_program_authority;
GRANT INSERT(program_id, class_id, actor_verifier_id, target_verifier_id, action, role_grant_id, assignment_id, transfer_id, old_owner_id, new_owner_id, occurred_at) ON public.classroom_audit_events TO c37_program_authority;
GRANT INSERT(email, display_name, pin_hash, created_at, updated_at), UPDATE(display_name) ON public.trusted_verifiers TO c37_program_authority;
GRANT UPDATE(name) ON public.organizations TO c37_program_authority;
GRANT UPDATE(display_name) ON public.classroom_classes TO c37_program_authority;
GRANT UPDATE(updated_at) ON public.classroom_class_states TO c37_program_authority;
GRANT UPDATE(display_name) ON public.woodchuck_profiles TO c37_program_authority;
GRANT UPDATE(created_at) ON public.classroom_student_memberships TO c37_program_authority;
GRANT SELECT(id) ON public.classroom_ownership_transfers TO c37_program_authority;
GRANT SELECT(id) ON public.classroom_audit_events TO c37_program_authority;
GRANT SELECT(id) ON public.classroom_role_grants TO c37_program_authority;
GRANT SELECT(id) ON public.classroom_teaching_assignments TO c37_program_authority;
GRANT SELECT(id) ON public.trusted_verifiers TO c37_program_authority;
GRANT USAGE ON SEQUENCE public.classroom_ownership_transfers_id_seq, public.classroom_audit_events_id_seq, public.classroom_role_grants_id_seq, public.classroom_teaching_assignments_id_seq, public.trusted_verifiers_id_seq TO c37_program_authority;
GRANT SELECT ON public.revoked_browser_sessions TO c37_program_authority;
COMMIT;
